<?php require_once __DIR__.'/../config/config.php'; require_admin(); $pdo=db(); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$title=trim($_POST['title']);$slug=slugify($title);$body=$_POST['body'];$published=isset($_POST['published'])?1:0;$img=upload_image($_FILES['image']??[]);if($id){$sql='UPDATE posts SET title=?,slug=?,body=?,published=?'.($img?',image=?':'').' WHERE id=?';$a=[$title,$slug,$body,$published];if($img)$a[]=$img;$a[]=$id;$pdo->prepare($sql)->execute($a);}else{$pdo->prepare('INSERT INTO posts(title,slug,body,published,image) VALUES(?,?,?,?,?)')->execute([$title,$slug,$body,$published,$img]);}flash('ok','Post salvo.');redirect('posts.php');}$rows=$pdo->query('SELECT * FROM posts ORDER BY id DESC')->fetchAll();$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM posts WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}require __DIR__.'/includes/header.php';?><div class="content"><h1>Posts / Conteúdo</h1><div class="panel" style="margin:20px 0"><h2><?=$edit?'Editar':'Novo'?> post</h2><form class="form" method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label>Título<input required name="title" value="<?=e($edit['title']??'')?>"></label><label>Texto<textarea name="body" required><?=e($edit['body']??'')?></textarea></label><label>Imagem<input type="file" name="image" accept="image/*"></label><label><input type="checkbox" name="published" <?=($edit['published']??1)?'checked':''?>> Publicado</label><button class="btn">Salvar</button></form></div><div class="panel"><table class="table"><tr><th>Título</th><th>Status</th><th>Atualizado</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=$r['published']?'Publicado':'Rascunho'?></td><td><?=e($r['updated_at'])?></td><td><a class="btn" href="posts.php?edit=<?=$r['id']?>">Editar</a></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/includes/footer.php';
